ALTER TABLE "customer_subscriptions" DROP CONSTRAINT IF EXISTS "customer_subscriptions_status_check";--> statement-breakpoint
ALTER TABLE "customer_subscriptions" ADD COLUMN IF NOT EXISTS "payment_provider" varchar(16);--> statement-breakpoint
ALTER TABLE "customer_subscriptions" ADD COLUMN IF NOT EXISTS "cryptomus_invoice_uuid" varchar(64);--> statement-breakpoint
ALTER TABLE "customer_subscriptions" ADD COLUMN IF NOT EXISTS "cryptomus_payment_url" varchar(512);--> statement-breakpoint
ALTER TABLE "customer_subscriptions" ADD COLUMN IF NOT EXISTS "cryptomus_invoice_expires_at" timestamp with time zone;--> statement-breakpoint
CREATE UNIQUE INDEX IF NOT EXISTS "customer_subscriptions_cryptomus_invoice_idx" ON "customer_subscriptions" USING btree ("cryptomus_invoice_uuid") WHERE "customer_subscriptions"."cryptomus_invoice_uuid" IS NOT NULL;--> statement-breakpoint
ALTER TABLE "customer_subscriptions" DROP CONSTRAINT IF EXISTS "customer_subscriptions_payment_provider_check";--> statement-breakpoint
ALTER TABLE "customer_subscriptions" DROP CONSTRAINT IF EXISTS "customer_subscriptions_cryptomus_invoice_check";--> statement-breakpoint
ALTER TABLE "customer_subscriptions" ADD CONSTRAINT "customer_subscriptions_payment_provider_check" CHECK ("customer_subscriptions"."payment_provider" IS NULL OR "customer_subscriptions"."payment_provider" = 'cryptomus');--> statement-breakpoint
ALTER TABLE "customer_subscriptions" ADD CONSTRAINT "customer_subscriptions_cryptomus_invoice_check" CHECK (("customer_subscriptions"."payment_provider" IS NULL AND "customer_subscriptions"."cryptomus_invoice_uuid" IS NULL AND "customer_subscriptions"."cryptomus_payment_url" IS NULL AND "customer_subscriptions"."cryptomus_invoice_expires_at" IS NULL) OR ("customer_subscriptions"."payment_provider" = 'cryptomus' AND (("customer_subscriptions"."cryptomus_invoice_uuid" IS NULL AND "customer_subscriptions"."cryptomus_payment_url" IS NULL AND "customer_subscriptions"."cryptomus_invoice_expires_at" IS NULL) OR ("customer_subscriptions"."cryptomus_invoice_uuid" IS NOT NULL AND "customer_subscriptions"."cryptomus_payment_url" IS NOT NULL AND "customer_subscriptions"."cryptomus_invoice_expires_at" IS NOT NULL))));--> statement-breakpoint
ALTER TABLE "customer_subscriptions" ADD CONSTRAINT "customer_subscriptions_status_check" CHECK (("customer_subscriptions"."status" = 'unpaid' AND "customer_subscriptions"."paid_at" IS NULL AND "customer_subscriptions"."paid_by" IS NULL) OR ("customer_subscriptions"."status" = 'paid' AND "customer_subscriptions"."paid_at" IS NOT NULL AND "customer_subscriptions"."deleted_at" IS NULL AND ("customer_subscriptions"."paid_by" IS NOT NULL OR ("customer_subscriptions"."payment_provider" = 'cryptomus' AND "customer_subscriptions"."cryptomus_invoice_uuid" IS NOT NULL))));
